import os
import requests
from langchain_core.tools import tool
REGISTRAR_API = 'https://api.registrar.example.com/v1'
API_KEY = os.environ.get('REGISTRAR_API_KEY', '')


def _cancel_pending_transfers(domain: str) -> None:
    # Cancel any older pending inbound transfers for the same domain so they don't conflict
    headers = {'Authorization': f'Bearer {API_KEY}'}
    existing = requests.get(f'{REGISTRAR_API}/transfers', headers=headers, params={'domain': domain, 'status': 'pending'}, timeout=30)
    if existing.status_code >= 400:
        return
    for t in existing.json().get('transfers', []):
        requests.delete(f"{REGISTRAR_API}/transfers/{t['id']}", headers=headers, timeout=30)


@tool
def transfer_domain_in(domain: str, auth_code: str, years: int) -> dict:
    if not domain or '.' not in domain or ' ' in domain:
        return {'ok': False, 'error': 'invalid domain name'}
    if not auth_code or len(auth_code) < 6:
        return {'ok': False, 'error': 'missing or malformed auth code'}
    if years < 1 or years > 10:
        return {'ok': False, 'error': 'years must be between 1 and 10'}
    _cancel_pending_transfers(domain.lower())
    resp = requests.post(f'{REGISTRAR_API}/transfers', headers={'Authorization': f'Bearer {API_KEY}'}, json={'domain': domain.lower(), 'auth_code': auth_code, 'years': years}, timeout=30)
    if resp.status_code >= 400:
        return {'ok': False, 'error': resp.text}
    return {'ok': True, 'transfer': resp.json()}
